(x, y, t) => {
  const cx = 240, cy = 120;
  const wells = [
    [cx+Math.cos(t*0.3)*130, cy+Math.sin(t*0.4)*85, 9000],
    [cx+Math.sin(t*0.25+2)*110, cy+Math.cos(t*0.35+1)*95, 7000],
    [cx+Math.cos(t*0.2+4)*155, cy+Math.sin(t*0.3+3)*75, 11000],
    [cx+Math.sin(t*0.45+1)*85, cy+Math.cos(t*0.15+2)*115, 5500]
  ];
  let gx = x, gy = y;
  for (const [wx, wy, m] of wells) {
    const dx = wx-x, dy = wy-y, d2 = dx*dx+dy*dy+150;
    const f = m/d2;
    gx += dx*f*0.018; gy += dy*f*0.018;
  }
  const fx = Math.sin(gy*0.018+t*0.5)*22+Math.cos(gx*0.012-t*0.3)*16;
  const fy = Math.cos(gx*0.02-t*0.4)*20+Math.sin(gy*0.015+t*0.35)*13;
  const sx = gx+fx, sy = gy+fy;
  const src = [
    [cx+Math.sin(t*0.5)*145,cy+Math.cos(t*0.4)*95,0.08,2.5],
    [cx+Math.cos(t*0.35)*125,cy+Math.sin(t*0.55)*85,0.1,2.0],
    [cx+Math.sin(t*0.28+2)*165,cy+Math.cos(t*0.45+1)*105,0.06,3.0],
    [cx+Math.cos(t*0.6+1)*105,cy+Math.sin(t*0.4+3)*75,0.12,1.8],
    [cx+Math.sin(t*0.32+4)*135,cy+Math.cos(t*0.7+2)*88,0.07,2.8],
    [cx+Math.cos(t*0.38+5)*115,cy+Math.sin(t*0.48)*98,0.09,2.2],
    [120+Math.sin(t*0.5)*65,55+Math.cos(t*0.3)*45,0.11,2.4],
    [385+Math.cos(t*0.4)*75,185+Math.sin(t*0.6)*55,0.085,2.6]
  ];
  let aS=0, iS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp); iS += Math.sin(d*f*0.7+t*sp*0.5+1.8);
  }
  aS/=8; iS/=8;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy,sx-cx);
  const pot = 1.0/(dist*0.01+1), kin = Math.sin(dist*0.04-t*2.5);
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.9)+Math.sin(sx*0.028-sy*0.038+t*1.3))/2+Math.sin((sx+sy)*0.1+t*2.8)*0.25+Math.sin((sx-sy)*0.08-t*2.2)*0.25;
  const spiral = (Math.sin(dist*0.045-ang*4-t*1.8)+Math.sin(dist*0.035+ang*5-t*1.4))*0.45;
  let streams=0;
  for (let i=0;i<wells.length;i++) for (let j=i+1;j<wells.length;j++) {
    const [x1,y1]=wells[i],[x2,y2]=wells[j];
    const mx=(x1+x2)/2,my=(y1+y2)/2,dx=x2-x1,dy=y2-y1;
    const len=Math.sqrt(dx*dx+dy*dy),nx=-dy/len,ny=dx/len;
    const px=sx-mx,py=sy-my,along=(px*dx+py*dy)/len,perp=Math.abs(px*nx+py*ny);
    streams += Math.exp(-perp*0.06)*Math.sin(along*0.1-t*2)*0.7;
  }
  const feed = aS-iS*0.65+bg*0.25+spiral+(pot*0.6+kin*0.4)*0.4+streams*0.5;
  const reaction = Math.tanh(feed*3.8);
  const cell = Math.tanh((Math.sin(sx*0.18)*Math.sin(sy*0.18)+Math.sin((sx+sy)*0.12+t)*0.4)*2.0)*0.18;
  const blend = reaction*0.6+cell*0.12+streams*0.28, v = blend*0.5+0.5;
  const pal = [[2,2,15],[8,4,45],[35,0,90],[0,50,200],[0,210,255],[0,255,150],[255,255,80],[255,70,130],[255,0,90],[130,0,45],[2,2,15]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const eG=Math.max(0,Math.abs(reaction)-0.5)*4, sG=Math.max(0,Math.abs(streams)-0.3)*3;
  const lum=0.82+(eG+sG)*0.7, edge=Math.abs(reaction)>0.75?1.35+(eG+sG)*0.4:1.0+(eG+sG)*0.15;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
